255	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
256	        this.clinicService.saveOwner(owner);
257	        if (idempotencyKey != null) {
258	            idempotentCreates.put(idempotencyKey, owner.getId());
259	        }
260	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
261	        Map<String, Integer> householdSizes = householdSizes();
262	        applyMembership(ownerDto, owner, householdSizes);
263	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
264	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
265	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
266	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
267	        emitOwnerCreatedEvent(owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
268	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
269	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
270	        headers.setLocation(UriComponentsBuilder.newInstance()
271	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
272	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
273	    }
