421	    /**
422	     * The maximum number of owners permitted per city. Owner creation is rejected once the
423	     * owner's city already contains this many owners.
424	     */
425	    private static final int MAX_OWNERS_PER_CITY = 50;
426	
427	    /**
428	     * Counts how many existing owners live in the given city, compared case-insensitively.
429	     * This is evaluated before the new owner is persisted, so the owner being created is not
430	     * included in the count.
431	     *
432	     * @param city the new owner's city
433	     * @return the number of existing owners in that city
434	     */
435	    private int countOwnersInCity(String city) {
436	        int count = 0;
437	        for (Owner existing : this.clinicService.findAllOwners()) {
438	            if (city.equalsIgnoreCase(existing.getCity())) {
439	                count++;
440	            }
441	        }
442	        return count;
443	    }
