445	    /**
446	     * The number of owners in a city at or above which a capacity warning is raised. Once the
447	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
448	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
449	     * {@code true} in the owner response.
450	     */
451	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
452	
453	    /**
454	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
455	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
456	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
457	     * create is rejected outright, so a full city never warns.
458	     *
459	     * @param city the owner's city
460	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
461	     */
462	    private boolean isApproachingCapacity(String city) {
463	        int count = countOwnersInCity(city);
464	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
465	    }
