467	    /**
468	     * The maximum number of owners that may be created in a single business day. Owner
469	     * creation is rejected once this many owners already fall on the new owner's adjusted
470	     * business day {@code registrationDate}.
471	     */
472	    private static final int MAX_OWNERS_PER_DAY = 100;
473	
474	    /**
475	     * The fixed list of public holidays that the business-day roll skips over. A date that
476	     * lands on one of these is rolled forward to the next non-holiday business day.
477	     */
478	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
479	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
480	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
481	        LocalDate.parse("2026-12-28"));
482	
483	    /**
484	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
485	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
486	     * while a date that is already a non-holiday weekday is returned unchanged.
487	     *
488	     * @param date the date to adjust
489	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
490	     */
491	    private LocalDate toBusinessDay(LocalDate date) {
492	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
493	                || PUBLIC_HOLIDAYS.contains(date)) {
494	            date = date.plusDays(1);
495	        }
496	        return date;
497	    }
