499	    /**
500	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
501	     * registrationDate} rolls forward to the same business day. This is evaluated before the
502	     * new owner is persisted, so the owner being created is not included in the count.
503	     *
504	     * @param businessDay the adjusted business day to count against
505	     * @return the number of existing owners registered on that business day
506	     */
507	    private int countOwnersRegisteredOn(LocalDate businessDay) {
508	        int count = 0;
509	        for (Owner existing : this.clinicService.findAllOwners()) {
510	            LocalDate existingDate = existing.getRegistrationDate();
511	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
512	                count++;
513	            }
514	        }
515	        return count;
516	    }
