536	    /**
537	     * Builds the customer code for a newly created owner, formatted
538	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
539	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
540	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
541	     * first eight upper-case hex characters of the SHA-256 digest of
542	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
543	     * stable for a given telephone and last name rather than dependent on creation order.
544	     *
545	     * @param postcode            the owner's postcode (may be {@code null})
546	     * @param normalizedTelephone the owner's normalized E.164 telephone
547	     * @param lastName            the owner's last name
548	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
549	     */
550	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
551	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
552	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
553	    }
554	
555	    /**
556	     * De-duplicates a freshly computed {@code base} customer code against the codes already
557	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
558	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
559	     * yields a code no existing owner holds.
560	     *
561	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
562	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
563	     */
564	    private String deduplicatedCustomerCode(String base) {
565	        Set<String> existing = new HashSet<>();
566	        for (Owner owner : this.clinicService.findAllOwners()) {
567	            if (owner.getCustomerCode() != null) {
568	                existing.add(owner.getCustomerCode());
569	            }
570	        }
571	        if (!existing.contains(base)) {
572	            return base;
573	        }
574	        int n = 2;
575	        while (existing.contains(base + "-" + n)) {
576	            n++;
577	        }
578	        return base + "-" + n;
579	    }
580	
581	    /**
582	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
583	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
584	     *
585	     * @param source the string to hash
586	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
587	     */
588	    private static String sha256Hex8(String source) {
589	        try {
590	            byte[] digest = MessageDigest.getInstance("SHA-256")
591	                .digest(source.getBytes(StandardCharsets.UTF_8));
592	            StringBuilder hex = new StringBuilder(digest.length * 2);
593	            for (byte b : digest) {
594	                hex.append(String.format("%02x", b));
595	            }
596	            return hex.substring(0, 8).toUpperCase();
597	        } catch (NoSuchAlgorithmException e) {
598	            throw new IllegalStateException("SHA-256 not available", e);
599	        }
600	    }
601	
602	    /**
603	     * Builds the membership number for a newly created owner, formatted
604	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
605	     * customer code and {@code YY} is the last two digits of the fiscal year of the owner's
606	     * business-day-adjusted registration date, zero-padded to two digits. The fiscal year
607	     * starts on 1 July and is named by the calendar year it ends in.
608	     *
609	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
610	     * @param registrationDate the owner's business-day-adjusted registration date
611	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M27'})
612	     */
613	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
614	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
615	        return String.format("%s-M%02d", customerCode, Math.floorMod(fiscalYear, 100));
616	    }
