638	    /**
639	     * Canonical expansions applied to common street-type abbreviations during address
640	     * normalization. Keys and values are upper-cased so the lookup runs after the address
641	     * has itself been upper-cased.
642	     */
643	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
644	        "ST", "STREET",
645	        "RD", "ROAD",
646	        "AVE", "AVENUE");
647	
648	    /**
649	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
650	     * every run of internal whitespace is collapsed to a single space, the result is
651	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
652	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
653	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
654	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
655	     * returned and compared for household duplicates; an address that is blank once
656	     * normalized fails the required-field check.
657	     *
658	     * @param address the raw address value supplied by the client
659	     * @return the normalized address (empty string when {@code address} is null or blank)
660	     */
661	    /**
662	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
663	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
664	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
665	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
666	     * address returned is the normalized {@code addressLine1} with a single space and the
667	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
668	     * the flat {@code address} is normalized and returned, and the structured lines are left
669	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
670	     * downstream (household hash, postcode validation and locality); an owner that supplies
671	     * neither form yields an empty string, failing the required-address check.
672	     *
673	     * @param owner          the owner being created, whose structured address lines are set here
674	     * @param ownerFieldsDto the submitted owner fields
675	     * @return the composed, normalized address (empty string when no address form is supplied)
676	     */
677	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
678	        String addressLine1 = ownerFieldsDto.getAddressLine1();
679	        if (addressLine1 != null && !addressLine1.isBlank()) {
680	            String normalizedLine1 = normalizeAddress(addressLine1);
681	            owner.setAddressLine1(normalizedLine1);
682	            String addressLine2 = ownerFieldsDto.getAddressLine2();
683	            if (addressLine2 != null && !addressLine2.isBlank()) {
684	                String normalizedLine2 = normalizeAddress(addressLine2);
685	                owner.setAddressLine2(normalizedLine2);
686	                return normalizedLine1 + " " + normalizedLine2;
687	            }
688	            owner.setAddressLine2(null);
689	            return normalizedLine1;
690	        }
691	        owner.setAddressLine1(null);
692	        owner.setAddressLine2(null);
693	        return normalizeAddress(ownerFieldsDto.getAddress());
694	    }
695	
696	    private static String normalizeAddress(String address) {
697	        if (address == null) {
698	            return "";
699	        }
700	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
701	        if (collapsed.isEmpty()) {
702	            return "";
703	        }
704	        StringBuilder normalized = new StringBuilder(collapsed.length());
705	        for (String token : collapsed.split(" ")) {
706	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
707	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
708	            if (normalized.length() > 0) {
709	                normalized.append(' ');
710	            }
711	            normalized.append(expanded != null ? expanded : token);
712	        }
713	        return normalized.toString();
714	    }
715	
716	    /**
717	     * Normalizes a last name or address for household-duplicate comparison: leading and
718	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
719	     * single space and the result is lower-cased. Two owners are considered to share a
720	     * household when both their last names and addresses produce the same key.
721	     *
722	     * @param value the raw last name or address value
723	     * @return the normalized comparison key (empty string when {@code value} is null)
724	     */
725	    private static String householdKey(String value) {
726	        if (value == null) {
727	            return "";
728	        }
729	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
730	    }
731	
732	    /**
733	     * Derives the stable shared household identifier for the given normalized last name key
734	     * and postcode. The identifier is deterministic — the same household (same
735	     * {@link #householdKey normalized} last name and postcode) always maps to the same
736	     * value — so every owner in a household is assigned an identical id. It is the
737	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
738	     * '<lastNameKey>|<postcode>'}.
739	     *
740	     * @param lastNameKey the normalized last name key
741	     * @param postcode    the owner's postcode
742	     * @return the shared household identifier
743	     */
744	    private static String householdId(String lastNameKey, String postcode) {
745	        String source = lastNameKey + "|" + postcode;
746	        try {
747	            byte[] digest = MessageDigest.getInstance("SHA-256")
748	                .digest(source.getBytes(StandardCharsets.UTF_8));
749	            StringBuilder hex = new StringBuilder(digest.length * 2);
750	            for (byte b : digest) {
751	                hex.append(String.format("%02x", b));
752	            }
753	            return hex.substring(0, 12).toUpperCase();
754	        } catch (NoSuchAlgorithmException e) {
755	            throw new IllegalStateException("SHA-256 not available", e);
756	        }
757	    }
758	
759	    /**
760	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
761	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
762	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
763	     * collides with a computed household id.
764	     *
765	     * @param owner the existing owner
766	     * @return the owner's household id, or {@code null} when it has no postcode
767	     */
768	    private static String computeHouseholdId(Owner owner) {
769	        if (owner.getPostcode() == null) {
770	            return null;
771	        }
772	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
773	    }
774	
775	    /**
776	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
777	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
778	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
779	     * when mapping a collection to size every household from a single scan.
780	     *
781	     * @param ownerDto the dto to populate
782	     * @param owner    the owner being mapped
783	     */
784	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
785	        applyMembership(ownerDto, owner, householdSizes());
786	    }
787	
788	    /**
789	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
790	     * dto using a pre-computed map of household id to member count.
791	     *
792	     * @param ownerDto       the dto to populate
793	     * @param owner          the owner being mapped
794	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
795	     */
796	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
797	        int householdSize = owner.getHouseholdId() == null ? 1
798	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
799	        int points = MembershipPoints.points(owner, householdSize);
800	        ownerDto.setMembershipPoints(points);
801	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
802	    }
803	
804	    /**
805	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
806	     * {@code membershipLevel} among the other current members of its household, writing the
807	     * capped value back onto the dto and returning it. A member's current level is scored the
808	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
809	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
810	     * has no household, or is the only member of its household, no cap applies and the level is
811	     * returned unchanged.
812	     *
813	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
814	     * @param owner          the newly created owner (already saved, so it has an id)
815	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
816	     * @return the resulting (possibly capped) membership level
817	     */
818	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
819	        Map<String, Integer> householdSizes) {
820	        int level = ownerDto.getMembershipLevel();
821	        String householdId = owner.getHouseholdId();
822	        if (householdId == null) {
823	            return level;
824	        }
825	        Integer maxMemberLevel = null;
826	        for (Owner existing : this.clinicService.findAllOwners()) {
827	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
828	                continue;
829	            }
830	            if (householdId.equals(existing.getHouseholdId())) {
831	                int size = householdSizes.getOrDefault(householdId, 1);
832	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
833	                maxMemberLevel = maxMemberLevel == null ? memberLevel
834	                    : Math.max(maxMemberLevel, memberLevel);
835	            }
836	        }
837	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
838	            level = maxMemberLevel + 1;
839	            ownerDto.setMembershipLevel(level);
840	        }
841	        return level;
842	    }
843	
844	    /**
845	     * Counts how many owners belong to each household, keyed by household id. Owners without a
846	     * household id (no postcode) are excluded — such an owner is its own single-member household.
847	     *
848	     * @return a map from household id to the number of owners sharing it
849	     */
850	    private Map<String, Integer> householdSizes() {
851	        Map<String, Integer> sizes = new java.util.HashMap<>();
852	        for (Owner existing : this.clinicService.findAllOwners()) {
853	            String householdId = existing.getHouseholdId();
854	            if (householdId != null) {
855	                sizes.merge(householdId, 1, Integer::sum);
856	            }
857	        }
858	        return sizes;
859	    }
860	
861	    /**
862	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
863	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
864	     * possible duplicate when a non-deleted existing owner shares its {@link
865	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
866	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
867	     * Because the telephone is part of the identity key, two owners with the same last name and
868	     * postcode but different telephones differ in their keys and so surface here as a soft match
869	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
870	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
871	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
872	     * matching id is recorded.
873	     *
874	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
875	     */
876	    private void applyPossibleDuplicate(Owner owner) {
877	        owner.setPossibleDuplicate(false);
878	        if (owner.getPostcode() == null) {
879	            return;
880	        }
881	        String soundex = OwnerIdentity.soundex(owner.getLastName());
882	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
883	        Owner match = null;
884	        for (Owner existing : this.clinicService.findAllOwners()) {
885	            if (existing.isDeleted()) {
886	                continue;
887	            }
888	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
889	                && owner.getPostcode().equals(existing.getPostcode())
890	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
891	                    existing.getEmail(), existing.getLastName()))) {
892	                if (match == null || (existing.getId() != null
893	                    && existing.getId() < match.getId())) {
894	                    match = existing;
895	                }
896	            }
897	        }
898	        if (match != null) {
899	            owner.setPossibleDuplicate(true);
900	            owner.setPossibleDuplicateOf(match.getId());
901	        }
902	    }
903	
904	    /**
905	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
906	     * and brackets are stripped. When the number already carries a leading {@code '+'}
907	     * and country code these are kept; a number written in national trunk form (a leading
908	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
909	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
910	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
911	     * after the {@code '+'}, and its national-number length must be valid for the detected
912	     * country code (see {@link #hasValidNationalLength}).
913	     *
914	     * @param telephone the raw telephone value supplied by the client
915	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
916	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
917	     */
918	    private static String toE164(String telephone) {
919	        if (telephone == null) {
920	            return null;
921	        }
922	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
923	        String digits;
924	        if (cleaned.startsWith("+")) {
925	            digits = cleaned.substring(1);
926	        } else if (cleaned.startsWith("0")) {
927	            digits = "61" + cleaned.substring(1);
928	        } else {
929	            digits = "1" + cleaned;
930	        }
931	        if (!digits.matches("[0-9]{8,15}")) {
932	            return null;
933	        }
934	        if (!hasValidNationalLength(digits)) {
935	            return null;
936	        }
937	        return "+" + digits;
938	    }
939	
940	    /**
941	     * Validates the national-number length of an E.164 digit string against its country
942	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
943	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
944	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
945	     *
946	     * @param digits the E.164 digits (without the leading {@code '+'})
947	     * @return {@code true} when the national-number length is valid for the country code
948	     */
949	    private static boolean hasValidNationalLength(String digits) {
950	        if (digits.startsWith("61")) {
951	            return digits.length() - 2 == 9;
952	        }
953	        if (digits.startsWith("1")) {
954	            return digits.length() - 1 == 10;
955	        }
956	        return true;
957	    }
958	
959	    /**
960	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
961	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
962	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
963	     */
964	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
965	        "NSW", new int[] {2000, 2099},
966	        "VIC", new int[] {3000, 3099},
967	        "QLD", new int[] {4000, 4099});
968	
969	    /**
970	     * Validates an owner's postcode for creation. A postcode is only ever validated when
971	     * present (an absent postcode is optional and accepted). When present it must be exactly
972	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
973	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
974	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
975	     *
976	     * @param postcode the supplied postcode (never {@code null} here)
977	     * @param city     the owner's city, used to derive the region
978	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
979	     *         (signalling a 400 Bad Request)
980	     */
981	    private static boolean isValidPostcode(String postcode, String city) {
982	        if (!postcode.matches("[0-9]{4}")) {
983	            return false;
984	        }
985	        int[] range = REGION_POSTCODES.get(
986	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
987	        if (range == null) {
988	            return true;
989	        }
990	        int value = Integer.parseInt(postcode);
991	        return value >= range[0] && value <= range[1];
992	    }
993	
994	    /**
995	     * Disposable email domains that are not accepted for owner creation. An owner whose
996	     * email domain (compared case-insensitively) is in this set is rejected with a 400
997	     * Bad Request.
998	     */
999	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
1000	        "mailinator.com", "tempmail.com", "guerrillamail.com");
1001	
1002	    /**
1003	     * Normalizes an owner email for creation. A present email must be a syntactically
1004	     * valid address whose domain is not on the disposable-domain blocklist ({@link
1005	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
1006	     *
1007	     * @param email the raw email value supplied by the client (never {@code null} here)
1008	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
1009	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
1010	     */
1011	    private static String normalizeEmail(String email) {
1012	        String trimmed = email.trim();
1013	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
1014	            return null;
1015	        }
1016	        String normalized = trimmed.toLowerCase();
1017	        String domain = normalized.substring(normalized.indexOf('@') + 1);
1018	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
1019	            return null;
1020	        }
1021	        return normalized;
1022	    }
1023	}
